/* Configuración conceptual de región MPU en Cortex-M para pila no ejecutable */
MPU->RBAR = (RAM_STACK_BASE & MPU_RBAR_ADDR_Msk) | MPU_RBAR_VALID_Msk | 0;
MPU->RASR = MPU_RASR_ENABLE_Msk |
            (1U << MPU_RASR_XN_Pos) |      /* Execute-Never: bloquea shellcode en stack */
            (0x03U << MPU_RASR_AP_Pos) |   /* RW solo privilegiado / o restringido */
            (13U << MPU_RASR_SIZE_Pos);    /* Tamaño 16 KB */
